import React, { lazy, Suspense } from 'react';
import './index.css';
import Home from './pages/Home';

// Lazy load the SplineEmbed component
const SplineEmbed = lazy(() => import('./components/SplineEmbed'));

function App() {
  return (
    <div>
      <Home />
      <Suspense fallback={<div className="text-center text-gray-600">Loading...</div>}>
        <SplineEmbed />
      </Suspense>
    </div>
  );
}

export default App;
